import {addressKey,taskLabels,TASK_GROUPS} from './domain.js?v=0.12.0';
export const doNotText=(state,address)=>!!state.addressNotes?.[addressKey(address)]?.doNotText;
export function setAddressPreference(state,address,key,value){state.addressNotes??={};state.addressNotes[addressKey(address)]={barkingDog:false,...state.addressNotes[addressKey(address)],[key]:!!value};}
export function mergeOrders(state,shiftId,ids,batchId){const unique=[...new Set(ids)],selected=state.deliveries.filter(d=>unique.includes(d.id));if(selected.length!==unique.length||selected.length<1||selected.some(d=>d.shiftId!==shiftId||!['pending','ready'].includes(d.status)||d.batchId)||state.runs.some(r=>r.status==='active'&&r.deliveryIds.some(id=>unique.includes(id))))throw Error('Choose at least one pending or ready single orders from this shift.');for(const [i,d] of selected.entries()){d.batchId=batchId;d.deliveryMode='batch';d.batchPosition=i;}return batchId;}
export function moveOrderToBatch(state,deliveryId,batchId){const d=state.deliveries.find(d=>d.id===deliveryId),members=state.deliveries.filter(x=>x.batchId===batchId&&x.status!=='canceled');if(!d||!['pending','ready'].includes(d.status)||d.batchId||!members.length||members.some(x=>x.shiftId!==d.shiftId)||members.every(x=>x.status==='delivered')||state.runs.some(r=>r.status==='active'&&r.deliveryIds.includes(d.id)))throw Error('Only a pending or ready single order can join an unfinished batch.');d.batchId=batchId;d.deliveryMode='batch';d.batchPosition=Math.max(-1,...members.map(x=>x.batchPosition??0))+1;const run=state.runs.find(r=>r.status==='active'&&r.batchId===batchId&&r.shiftId===d.shiftId);if(run&&d.status==='ready'){if(!run.deliveryIds.includes(d.id))run.deliveryIds.push(d.id);d.status='active';d.departedAt=new Date().toISOString();}}
export function requireCateringPhotos(d,{allowException=false}={}){if(d.isCatering&&!(allowException&&d.cateringPhotoException?.confirmedAt)&&(!d.cateringPhotos?.setup?.data||!d.cateringPhotos?.receipt?.data))throw Error('Add both the set-up and receipt photos to share them. To finish delivery without both photos, use the explicit completion confirmation.');}
export function alcoholReturns(state,run){return run.deliveryIds.map(id=>state.deliveries.find(d=>d.id===id)).filter(d=>d?.hasAlcohol&&d.status==='delivered');}
export function detailCSVRows(state,shifts){const headers=['record_type','shift_id','shift_started_at','shift_ended_at','shift_start_odometer','shift_end_odometer','delivery_id','run_id','run_started_at','run_returned_at','run_kind','batch_id','customer_name','customer_phone','delivery_address','ticket','status','entered_at','ready_at','departed_at','delivered_at','scheduled_at','drinks_or_ice_cream','cold_item_details','cold_items_confirmed_at','alcohol','needs_signature','catering','setup_photo_recorded','setup_photo_captured_at','receipt_photo_recorded','receipt_photo_captured_at','do_not_text_address','barking_dog_address','task','task_completed_at','delivery_notes','catering_photo_exception_confirmed_at','shift_data_quality','shift_note'];const rows=[headers],add=value=>rows.push(headers.map(k=>value[k]??''));for(const s of shifts){const base={shift_id:s.id,shift_started_at:s.startedAt,shift_ended_at:s.endedAt,shift_start_odometer:s.startOdometer,shift_end_odometer:s.endOdometer,shift_data_quality:s.runDataQuality||'',shift_note:s.fieldTestNote||''};add({...base,record_type:'shift'});for(const d of state.deliveries.filter(d=>d.shiftId===s.id)){const r=state.runs.filter(r=>r.deliveryIds.includes(d.id)).sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt))[0];add({...base,record_type:'delivery',delivery_id:d.id,run_id:r?.id,run_started_at:r?.startedAt,run_returned_at:r?.returnedAt,run_kind:r?.kind||'',batch_id:d.batchId,customer_name:d.name,customer_phone:d.phone,delivery_address:d.address,ticket:d.ticket,delivery_notes:d.notes||'',catering_photo_exception_confirmed_at:d.cateringPhotoException?.confirmedAt||'',status:d.status,entered_at:d.enteredAt,ready_at:d.readyAt,departed_at:d.departedAt||r?.startedAt,delivered_at:d.completedAt,scheduled_at:d.scheduledAt,drinks_or_ice_cream:d.hasColdItems?'YES':'NO',cold_item_details:d.coldItemDetails,cold_items_confirmed_at:d.coldItemsConfirmedAt,alcohol:d.hasAlcohol?'YES':'NO',needs_signature:d.needsSignature||d.hasAlcohol?'YES':'NO',catering:d.isCatering?'YES':'NO',setup_photo_recorded:d.cateringPhotos?.setup?'YES':'NO',setup_photo_captured_at:d.cateringPhotos?.setup?.capturedAt,receipt_photo_recorded:d.cateringPhotos?.receipt?'YES':'NO',receipt_photo_captured_at:d.cateringPhotos?.receipt?.capturedAt,do_not_text_address:doNotText(state,d.address)?'YES':'NO',barking_dog_address:state.addressNotes?.[addressKey(d.address)]?.barkingDog?'YES':'NO'});}const labels=new Map(TASK_GROUPS.flatMap(g=>g.children?g.children.map(c=>[g.label+': '+c,g.id+':'+c]):[[g.label,g.id]]));for(const label of taskLabels(s.tasks||{}))add({...base,record_type:'task',task:label,task_completed_at:s.taskCompletedAt?.[labels.get(label)||'special']});}return rows;}
